            ['157', 'Не превращать поиск в бегство', 'Единица символизирует намерение, пятёрка — движение, семёрка — внутреннее исследование. Число 157 напоминает: иногда мы меняем книги, практики и наставников быстрее, чем успеваем проверить хоть одну идею в собственной жизни. Поиск становится полезным, когда возвращает к действию.', 'Любознательность, подкреплённая личным опытом.', 'Постоянная смена подходов ради обещания скорого ответа.', 'Что я уже узнал, но ещё ни разу не применил?', 'Выбери одну знакомую практику и повторяй её несколько дней без поиска новой.'],
            ['158', 'Не продавать себе иллюзию свободы', 'Единица символизирует выбор, пятёрка — свободу, восьмёрка — ресурсы. Число 158 напоминает: желание независимости иногда превращается в гонку за статусом, который лишь увеличивает зависимость от чужого восхищения. Важно понимать, что именно должны обеспечивать достижения.', 'Ресурсы, поддерживающие самостоятельные решения.', 'Покупка символов успеха ради ощущения внутренней свободы.', 'Какая моя трата обещает изменить самоощущение, но вряд ли изменит жизнь?', 'Перед необязательной покупкой запиши её реальную пользу и эмоциональное ожидание.'],
            ['159', 'Оставить прежнюю версию свободы', 'Единица символизирует личный выбор, пятёрка — перемены, девятка — завершение. Число 159 напоминает, что свобода на разных этапах жизни может выглядеть по-разному. То, что раньше означало независимость, сегодня может мешать близости, устойчивости или покою.', 'Готовность пересматривать свои представления о свободе.', 'Привязанность к старому образу себя как к обязательному доказательству независимости.', 'Что я называю свободой по привычке, хотя больше этого не хочу?', 'Закончи фразу: «Сегодня для меня быть свободным — значит…».']
  ];
  foreach ($entries as $entry) {
   [$number,$title,$symbolism,$light,$shadow,$question,$practice] = $entry;
   $record = NumberMeaning::query()->where('number',$number)->first();
   if (!$record) { continue; }
   $text = (string) $record->symbolism;
   $generated = str_starts_with($text,'Число '.$number.' можно использовать как повод для самонаблюдения.')
    || str_starts_with($text,'Иногда мы замечаем число в тот момент')
    || str_starts_with($text,'Представь это число не как указание судьбы')
    || str_starts_with($text,'Не нужно верить, что совпадение что-то предсказывает')
    || str_starts_with($text,'У чисел нет обязанности объяснять нашу жизнь')
    || str_starts_with($text,'Смысл здесь рождается не в цифрах')
    || str_starts_with($text,'Попробуй на мгновение оставить поиск тайного послания');
   if (!$generated) { continue; }
   $record->update(['title'=>$title,'symbolism'=>$symbolism,'light_side'=>$light,'shadow_side'=>$shadow,'reflection_question'=>$question,'practice'=>$practice]);
  }
 }
